  "Женщина 61 год. HbA1c 6,8%, АД на приеме 152/94 мм рт.ст., повторно 148/92.": "Зан, 61 сола. HbA1c 6,8%, фишори хун дар қабул 152/94 мм сут. сим., такроран 148/92.",
